            var current = hit.getBlockPos();

            var maxUp = (int) Math.floor(radius - eyePos.distanceTo(hit.getLocation()));

            BlockPos feetPos = null;

            for (int i = 1; i <= maxUp && current.getY() + i < level.getMaxBuildHeight(); i++) {
                var feet = current.above(i);
                var head = feet.above();

